#!/bin/bash
# CDT Workflow Engine — self-extracting source bundle
# Usage:  bash cdt-src-bundle.sh [target-dir]
#         target-dir defaults to ./cdt-workflow-src

set -e
TARGET="${1:-cdt-workflow-src}"
echo "Extracting to: $TARGET"

decode() {
  local rel="$1"; shift
  local dest="$TARGET/$rel"
  mkdir -p "$(dirname "$dest")"
  printf '%s' "$*" | base64 -d > "$dest"
}
